# Generated by Descant: acceptance tests.

require "timekeeping_relay"

RSpec.describe TimekeepingRelay::FailureReason do
  it "a response reason carrying a token and a newline maps to unrecognized" do
    token = "svc-token-7f3a9c"
    hostile = TimekeepingRelay::Response.new(status: 401, body: { "reason" => "Bearer #{token}\nINFO forged line" })
    stale = TimekeepingRelay::Response.new(status: 409, body: { "reason" => "stale_generation" })

    reason = described_class.for(hostile)

    # "No token is written to a payload or a log line." The reason is logged, so it must never echo the response.
    expect(reason).to eq("unrecognized")
    expect(reason).not_to include(token)
    expect(reason).not_to include("\n")
    expect(described_class.for(stale)).to eq("stale_generation")
  end
end
